-- =========================================================
-- SCRIPT DE POBLADO - SISTEMA WEB DE GESTIÓN DE CITAS MÉDICAS
-- CLÍNICA "VIDA SALUD"
-- PostgreSQL 14+
--
-- Fuente del esquema: vida_salud.sql (esquema vida_salud, diseño v3)
-- Fuente del alcance funcional: documento Parcial 2 SI1, sección 1.4
--   (Alcance por módulos) + Excel "Resumen 36 Casos de Uso" (CU01–CU36,
--   paquetes P1–P7).
-- Simulación: 92 días de operación, del 2026-08-25 al 2026-11-24.
--   "Hoy" es el sábado 2026-10-24 (12:00): las citas anteriores ya están
--   ATENDIDAS, CANCELADAS o con INASISTENCIA; las posteriores están
--   PROGRAMADAS o CONFIRMADAS.
--   15 usuarios (1 administradora, 4 recepcionistas, 10 médicos),
--   7 especialidades, 70 pacientes, 296 citas, 612 cambios de estado,
--   277 recordatorios, 199 sesiones y 1035 registros de bitácora.
--   Feriados generales: 2026-09-24 (Aniversario de Santa Cruz) y
--   2026-11-02 (Todos los Difuntos): ese día no hay ninguna cita.
--
-- NOTA IMPORTANTE: los valores de "hash_contrasena" son cadenas de ejemplo
-- (formato similar a bcrypt), NO son hashes reales. En producción, el
-- backend genera el hash real (Laravel: Hash::make(); PHP puro:
-- password_hash()) antes de insertar en la tabla "usuario".
-- Lo mismo vale para "token_hash" de token_recuperacion: son SHA-256 de
-- ejemplo, no corresponden a ningún código real.
--
-- Ejecutar este script DESPUÉS de correr vida_salud.sql (que crea el
-- esquema, las tablas, los ENUM y las FK). Todas las FK son DEFERRABLE,
-- así que el script va dentro de una única transacción.
-- =========================================================

SET search_path TO vida_salud;
BEGIN;

-- =========================================================
-- 0. LIMPIEZA DEL SEED DEL DDL
-- Fuente: vida_salud.sql, sección "DATOS INICIALES"
-- vida_salud.sql ya inserta 3 roles y 10 permisos con id automático. Se
-- borran para volver a cargarlos aquí con ids explícitos y la matriz
-- completa de permisos.
-- =========================================================

DELETE FROM "rol_permiso";
DELETE FROM "permiso";
DELETE FROM "rol";

-- =========================================================
-- 1. BASE: PERSONA (superclase de paciente, medico y personal_administrativo)
-- Fuente: Documento §1.4.1, §1.4.2, §1.4.3; CU05, CU12, CU17
-- ids 1-5: personal administrativo · 6-15: médicos · 16-85: pacientes
-- =========================================================


-- =========================================================
-- 2. MÓDULO: ADMINISTRACIÓN DE USUARIOS RBAC (P2)
-- Fuente: Documento §1.4.1 (roles predefinidos); CU05–CU09
-- =========================================================



-- Administrador: todos los permisos · Recepcionista: pacientes y citas ·
-- Médico: su agenda, historial e información médica, marcar atendida (CU26, CU35).

-- Usuario 4 (jmendoza) fue bloqueado el 2026-10-05 por 3 intentos fallidos (CU04);
-- el bloqueo de 1 minuto ya venció, por eso hoy está ACTIVO con contador en 0.
-- Usuario 15 (médico dado de baja) quedó INACTIVO (CU09, CU19).


-- =========================================================
-- 3. MÓDULO: SEGURIDAD Y AUTENTICACIÓN (P1)
-- Fuente: Documento §1.4.1; CU01 (sesión), CU02 (cierre), CU03 (recuperación), CU04 (bloqueo)
-- Sesiones de la jornada laboral; las de hoy (2026-10-24) siguen activas.
-- Los intentos fallidos y el bloqueo de CU04 quedan en la bitácora (sección 8).
-- =========================================================



-- =========================================================
-- 4. MÓDULO: GESTIÓN DE PACIENTES (P4)
-- Fuente: Documento §1.4.2; CU12–CU15, CU31 (información médica), CU32 (contacto de emergencia)
-- Los 15 primeros pacientes (ids 16-30) son menores de edad: los atiende Pediatría.
-- El paciente 85 está dado de baja (persona.activo = false, CU15).
-- =========================================================




-- =========================================================
-- 5. MÓDULO: GESTIÓN MÉDICA Y HORARIOS (P5)
-- Fuente: Documento §1.4.3; CU16–CU19, CU33 (bloqueo de agenda)
-- =========================================================


-- Médico 15 (Hugo Flores Mamani) dado de baja el 2026-10-10 (CU19): conserva sus
-- citas pasadas pero no tiene citas desde esa fecha y sus horarios quedan inactivos.

-- Médicos con 2 especialidades: 8 (Pediatría + Medicina General), 11 (Cardiología +
-- Medicina General) y 15 (Traumatología + Medicina General).

-- dia_semana: 1 = lunes ... 6 = sábado. Turnos de 4 horas = 8 bloques de 30 minutos (CU18).

-- Feriados generales: id_medico NULL y aplica_a_todos = true (CU33).
-- Licencias: un médico concreto y aplica_a_todos = false.

-- =========================================================
-- 6. MÓDULO: GESTIÓN DE CITAS (P6)
-- Fuente: Documento §1.4.4; CU20–CU26, CU34 (recordatorio), CU35 (marcar atendida)
-- Bloque generado: 296 citas CM-0001..CM-0296, ordenadas por fecha de registro.
-- Estados: 145 ATENDIDA, 31 CANCELADA, 28 INASISTENCIA, 1 CONFIRMADA, 91 PROGRAMADA.
-- Reglas que cumple el bloque: solo en días y horas del horario de cada médico,
-- ninguna en fechas bloqueadas, sin dos citas del mismo médico a la misma hora,
-- Pediatría solo con menores y Ginecología solo con pacientes mujeres.
-- Reprogramaciones (CU23): CM-0130 -> CM-0148, CM-0068 -> CM-0075, CM-0053 -> CM-0059 (la nueva cita
-- lleva id_cita_origen; la original queda CANCELADA con el motivo).
-- =========================================================


-- Historial (CU23, CU24, CU25, CU35): 612 registros. Cada cita nace PROGRAMADA y
-- cada cambio posterior deja una fila. id_usuario: recepcionista, o el médico al marcar ATENDIDA.

-- Recordatorios telefónicos (CU34): 277 llamadas. El sistema arma la lista a las 08:00
-- del día hábil anterior; una recepcionista (usuarios 2–5) llama entre 08:30–12:00 o 14:30–18:00.
-- ENVIADA = llamado/confirmado; FALLIDA = no contestó o sin teléfono; PENDIENTE = aún por llamar.

-- =========================================================
-- 7. MÓDULO: REPORTES (P7)
-- Fuente: Documento §1.4.5; CU27–CU30, CU36
-- =========================================================


-- =========================================================
-- 8. MÓDULO: AUDITORÍA Y BITÁCORA (P3)
-- Fuente: Documento §1.4.6; CU10 (registro automático), CU11 (consulta)
-- 1035 eventos en orden cronológico: altas, inicios y cierres de sesión,
-- intentos fallidos (id_usuario NULL), bloqueo, citas, cancelaciones y reportes.
-- =========================================================


-- =========================================================
-- 9. AJUSTE DE SECUENCIAS DE IDENTIDAD
-- Fuente: las PK son GENERATED BY DEFAULT AS IDENTITY
-- Como aquí se insertó con id explícito, se mueve cada secuencia al máximo
-- id para que el próximo INSERT del sistema no choque.
-- =========================================================

SELECT setval(pg_get_serial_sequence('vida_salud.persona', 'id_persona'), (SELECT max("id_persona") FROM "persona"));
SELECT setval(pg_get_serial_sequence('vida_salud.rol', 'id_rol'), (SELECT max("id_rol") FROM "rol"));
SELECT setval(pg_get_serial_sequence('vida_salud.permiso', 'id_permiso'), (SELECT max("id_permiso") FROM "permiso"));
SELECT setval(pg_get_serial_sequence('vida_salud.usuario', 'id_usuario'), (SELECT max("id_usuario") FROM "usuario"));
SELECT setval(pg_get_serial_sequence('vida_salud.token_recuperacion', 'id_token'), (SELECT max("id_token") FROM "token_recuperacion"));
SELECT setval(pg_get_serial_sequence('vida_salud.informacion_medica', 'id_informacion'), (SELECT max("id_informacion") FROM "informacion_medica"));
SELECT setval(pg_get_serial_sequence('vida_salud.contacto_emergencia', 'id_contacto'), (SELECT max("id_contacto") FROM "contacto_emergencia"));
SELECT setval(pg_get_serial_sequence('vida_salud.especialidad', 'id_especialidad'), (SELECT max("id_especialidad") FROM "especialidad"));
SELECT setval(pg_get_serial_sequence('vida_salud.horario', 'id_horario'), (SELECT max("id_horario") FROM "horario"));
SELECT setval(pg_get_serial_sequence('vida_salud.bloqueo_agenda', 'id_bloqueo'), (SELECT max("id_bloqueo") FROM "bloqueo_agenda"));
SELECT setval(pg_get_serial_sequence('vida_salud.cita', 'id_cita'), (SELECT max("id_cita") FROM "cita"));
SELECT setval(pg_get_serial_sequence('vida_salud.historial_estado_cita', 'id_historial'), (SELECT max("id_historial") FROM "historial_estado_cita"));
SELECT setval(pg_get_serial_sequence('vida_salud.notificacion', 'id_notificacion'), (SELECT max("id_notificacion") FROM "notificacion"));
SELECT setval(pg_get_serial_sequence('vida_salud.reporte', 'id_reporte'), (SELECT max("id_reporte") FROM "reporte"));
SELECT setval(pg_get_serial_sequence('vida_salud.bitacora', 'id_bitacora'), (SELECT max("id_bitacora") FROM "bitacora"));

COMMIT;

-- =========================================================
-- 10. VERIFICACIÓN DE CONSISTENCIA
-- Fuente: consultas de control; deben devolver lo indicado en cada comentario
-- =========================================================

-- Cantidad de filas por tabla.
SELECT 'persona' AS tabla, count(*) FROM persona UNION ALL SELECT 'usuario', count(*) FROM usuario UNION ALL SELECT 'paciente', count(*) FROM paciente UNION ALL SELECT 'medico', count(*) FROM medico UNION ALL SELECT 'cita', count(*) FROM cita UNION ALL SELECT 'historial_estado_cita', count(*) FROM historial_estado_cita UNION ALL SELECT 'notificacion', count(*) FROM notificacion UNION ALL SELECT 'bitacora', count(*) FROM bitacora;
-- Citas por estado.
SELECT estado, count(*) FROM cita GROUP BY estado ORDER BY estado;
-- Debe dar 0: llamadas de CU34 hechas por alguien que no es recepcionista o fuera de horario (08:30-18:00).
SELECT count(*) AS llamadas_incoherentes FROM notificacion n LEFT JOIN usuario u ON u.id_usuario = n.id_usuario_gestion WHERE n.estado <> 'PENDIENTE' AND (u.id_rol IS DISTINCT FROM 2 OR (n.fecha_envio AT TIME ZONE 'America/La_Paz')::time NOT BETWEEN '08:30' AND '20:00' OR n.fecha_envio::date >= (SELECT c.fecha FROM cita c WHERE c.id_cita = n.id_cita));
-- Debe dar 0: ninguna cita en fechas bloqueadas (feriados generales o licencias).
SELECT count(*) AS citas_en_fecha_bloqueada FROM cita c JOIN bloqueo_agenda b ON c.fecha BETWEEN b.fecha_inicio AND b.fecha_fin AND (b.id_medico IS NULL OR b.id_medico = c.id_medico);
-- Debe dar 0: ninguna cita fuera del horario del médico.
SELECT count(*) AS citas_fuera_de_horario FROM cita c WHERE NOT EXISTS (SELECT 1 FROM horario h WHERE h.id_medico = c.id_medico AND h.dia_semana = EXTRACT(ISODOW FROM c.fecha) AND c.hora_inicio >= h.hora_inicio AND c.hora_fin <= h.hora_fin);
-- Debe dar 0: citas pasadas que siguen PROGRAMADAS/CONFIRMADAS, o futuras ya cerradas.
SELECT count(*) AS estados_incoherentes FROM cita WHERE (fecha + hora_inicio < '2026-10-24 12:00' AND estado IN ('PROGRAMADA','CONFIRMADA')) OR (fecha + hora_inicio >= '2026-10-24 12:00' AND estado IN ('ATENDIDA','INASISTENCIA'));
-- Debe dar 0: citas cuyo último estado del historial no coincide con cita.estado.
SELECT count(*) AS historial_incoherente FROM cita c WHERE c.estado <> (SELECT h.estado_nuevo FROM historial_estado_cita h WHERE h.id_cita = c.id_cita ORDER BY h.fecha_cambio DESC, h.id_historial DESC LIMIT 1);
-- Debe dar 0: citas del médico dado de baja posteriores a su baja.
SELECT count(*) AS citas_medico_baja FROM cita WHERE id_medico = 15 AND fecha >= '2026-10-10';
